import { Ionicons } from "@expo/vector-icons";
import { useQuery } from "@tanstack/react-query";
import { ActivityIndicator, StyleSheet, Text, View } from "react-native";
import { Screen } from "../../ui/Screen";
import { colors, radius, spacing } from "../../ui/tokens";
import { firebaseAuth } from "../auth/firebase";
import { getVendorReturns } from "./vendor.api";

export function VendorReturnsScreen() {
  const user = firebaseAuth?.currentUser ?? null;
  const query = useQuery({ queryKey: ["vendor", "returns"], queryFn: () => getVendorReturns(user!), enabled: Boolean(user) });
  const open = query.data?.filter((item) => !["REFUNDED", "REJECTED", "CLOSED"].includes(item.status)).length ?? 0;
  const requested = query.data?.reduce((sum, item) => sum + Number(item.requestedAmount.amountMinor), 0) ?? 0;
  return <Screen eyebrow="AFTER SALES" title="Customer returns" description="Track return requests, inspection progress and refund exposure for your orders.">
    <View style={styles.metrics}><Metric icon="return-down-back-outline" label="Total returns" value={String(query.data?.length ?? 0)} /><Metric icon="time-outline" label="Open cases" value={String(open)} /><Metric icon="cash-outline" label="Requested value" value={`৳${(requested / 100).toLocaleString("en-BD")}`} /></View>
    {query.isLoading ? <ActivityIndicator color={colors.primary} /> : null}
    <View style={styles.list}>{query.data?.map((item) => <View key={item.id} style={styles.card}><View style={styles.cardHeader}><View><Text style={styles.number}>RETURN #{item.id.slice(0, 8).toUpperCase()}</Text><Text style={styles.date}>{new Date(item.createdAt).toLocaleDateString("en-BD", { day: "numeric", month: "short", year: "numeric" })}</Text></View><Text style={styles.status}>{item.status.replaceAll("_", " ")}</Text></View><View style={styles.reason}><Ionicons color={colors.primary} name="information-circle-outline" size={21} /><View style={styles.flex}><Text style={styles.reasonTitle}>{item.reasonCode.replaceAll("_", " ")}</Text><Text style={styles.muted}>{item.reasonDetail || "No additional customer note"}</Text></View></View><View style={styles.details}><Cell label="ORDER" value={`#${item.orderId.slice(0, 8).toUpperCase()}`} /><Cell label="ITEMS" value={String(item.items.reduce((sum, row) => sum + row.quantity, 0))} /><Cell label="REQUESTED" value={`৳${(Number(item.requestedAmount.amountMinor) / 100).toLocaleString("en-BD")}`} /><Cell label="APPROVED" value={item.approvedAmount ? `৳${(Number(item.approvedAmount.amountMinor) / 100).toLocaleString("en-BD")}` : "Pending"} /></View></View>)}</View>
    {!query.isLoading && !query.data?.length ? <View style={styles.empty}><Ionicons color={colors.success} name="checkmark-circle-outline" size={52} /><Text style={styles.emptyTitle}>No return requests</Text><Text style={styles.muted}>New customer return cases will appear here automatically.</Text></View> : null}{query.error ? <Text style={styles.error}>{query.error.message}</Text> : null}
  </Screen>;
}

function Metric({ icon, label, value }: { icon: React.ComponentProps<typeof Ionicons>["name"]; label: string; value: string }) { return <View style={styles.metric}><Ionicons color={colors.primary} name={icon} size={22} /><View><Text style={styles.metricValue}>{value}</Text><Text style={styles.metricLabel}>{label}</Text></View></View>; }
function Cell({ label, value }: { label: string; value: string }) { return <View style={styles.cell}><Text style={styles.cellLabel}>{label}</Text><Text style={styles.cellValue}>{value}</Text></View>; }
const styles = StyleSheet.create({ flex: { flex: 1 }, metrics: { flexDirection: "row", flexWrap: "wrap", gap: spacing.md }, metric: { alignItems: "center", backgroundColor: colors.surface, borderColor: colors.border, borderRadius: radius.lg, borderWidth: 1, flex: 1, flexDirection: "row", gap: spacing.md, minWidth: 210, padding: spacing.md }, metricValue: { color: colors.text, fontSize: 20, fontWeight: "900" }, metricLabel: { color: colors.muted, fontSize: 10, marginTop: 2 }, list: { gap: spacing.md }, card: { backgroundColor: colors.surface, borderColor: colors.border, borderRadius: radius.lg, borderWidth: 1, gap: spacing.md, padding: spacing.lg }, cardHeader: { alignItems: "flex-start", flexDirection: "row", justifyContent: "space-between" }, number: { color: colors.text, fontSize: 12, fontWeight: "900" }, date: { color: colors.muted, fontSize: 10, marginTop: 4 }, status: { backgroundColor: colors.primarySoft, borderRadius: radius.pill, color: colors.primary, fontSize: 8, fontWeight: "900", overflow: "hidden", paddingHorizontal: 9, paddingVertical: 6 }, reason: { alignItems: "flex-start", backgroundColor: "#f8fafc", borderRadius: radius.md, flexDirection: "row", gap: spacing.sm, padding: spacing.md }, reasonTitle: { color: colors.text, fontWeight: "900", textTransform: "capitalize" }, muted: { color: colors.muted, fontSize: 11, lineHeight: 18, marginTop: 3 }, details: { flexDirection: "row", flexWrap: "wrap", gap: spacing.sm }, cell: { backgroundColor: "#f8fafc", borderRadius: radius.md, flex: 1, minWidth: 130, padding: spacing.sm }, cellLabel: { color: colors.muted, fontSize: 8, fontWeight: "900" }, cellValue: { color: colors.text, fontSize: 12, fontWeight: "900", marginTop: 4 }, empty: { alignItems: "center", backgroundColor: colors.surface, borderColor: colors.border, borderRadius: radius.xl, borderStyle: "dashed", borderWidth: 1, gap: spacing.sm, padding: 42 }, emptyTitle: { color: colors.text, fontSize: 19, fontWeight: "900" }, error: { color: colors.danger } });
